<script>
    const sourceList = document.getElementById('research-source-list');
    const renumberSources = () => [...sourceList.querySelectorAll('[data-research-source]')].forEach((row, index) => row.querySelectorAll('[data-source-field]').forEach((field) => { field.name = `sources[${index}][${field.dataset.sourceField}]`; }));
    document.getElementById('add-research-source').addEventListener('click', () => { const row = document.createElement('div'); row.dataset.researchSource = ''; row.className = 'grid gap-3 rounded-2xl bg-[#f8f1e7] p-4 sm:grid-cols-[minmax(0,0.8fr)_minmax(0,1.4fr)_auto]'; row.innerHTML = '<label class="text-xs font-semibold text-[#685442]">名称<input data-source-field="label" maxlength="255" placeholder="企業公式サイト" class="mt-1.5 w-full rounded-lg border border-[#e8ddce] bg-white px-3 py-2.5 text-sm font-normal"></label><label class="text-xs font-semibold text-[#685442]">URL<input data-source-field="url" type="url" maxlength="2048" placeholder="https://..." class="mt-1.5 w-full rounded-lg border border-[#e8ddce] bg-white px-3 py-2.5 text-sm font-normal"></label><button type="button" data-remove-source class="self-end px-2 py-2.5 text-xs font-semibold text-[#a94736] hover:underline">削除</button>'; sourceList.append(row); renumberSources(); });
    sourceList.addEventListener('click', (event) => { if (event.target.closest('[data-remove-source]')) { event.target.closest('[data-research-source]').remove(); renumberSources(); } });
</script>
@endsection
